 ```js
import { gsap } from 'gsap';
import { MeshPhysicalNodeMaterial } from 'three/webgpu';
import {
  uv,
  vec2,
  vec3,
  vec4,
  texture,
  uniform,
  mix,
  smoothstep,
  abs,
  length,
  max,
  min,
  color,
  oneMinus
} from 'three/tsl';

export default function createNode(config, ctx) {
  const { THREE } = ctx;
  const { Group, PlaneGeometry, Vector2 } = THREE;

  const root = new Group();
  const pivot = new Group();
  root.add(pivot);

  const width = 1.2;
  const height = 0.36;
  const aspect = width / height;
  const geometry = new PlaneGeometry(width, height, 64, 24);
  geometry.computeBoundingSphere();

  const surfaceCol = color('#0b0b10');
  const inkCol = color('#16161d');
  const accentCol = color('#ff2a38');
  const paperCol = color('#e8ecf2');
  const edgeUniform = uniform(1.2);
  const ambientEdge = uniform(0.8);
  const aa = uniform(0.008);
  const edgeThick = uniform(0.035);

  const texPromise = config.imageUrl ? ctx.textureLoader.loadTexture(config.imageUrl) : Promise.resolve(null);

  let material;
  let mesh;
  let tex = null;
  const timelines = [];

  texPromise.then((loadedTex) => {
    tex = loadedTex;
    if (tex) {
      tex.colorSpace = THREE.SRGBColorSpace;
      tex.wrapS = THREE.RepeatWrapping;
      tex.wrapT = THREE.RepeatWrapping;
    }

    const uvs = uv();
    const qx = uvs.x.sub(0.5).mul(aspect);
    const qy = uvs.y.sub(0.5);
    const q = vec2(qx, qy);

    const size = vec2(aspect * 0.5 - 0.5, 0.0);
    const d = abs(q).sub(size);
    const signed = length(max(d, vec2(0.0, 0.0)))
      .add(min(max(d.x, d.y), 0.0))
      .sub(0.5);

    const alpha = smoothstep(aa, 0.0, signed);

    const borderDist = abs(signed);
    const borderMask = smoothstep(edgeThick.add(aa), edgeThick, borderDist);

    const baseNoise = tex ? texture(tex, uvs).r : 0.5;
    const baseColor = mix(surfaceCol, inkCol, baseNoise.mul(0.35));
    const edgeColor = accentCol.mul(edgeUniform);

    const finalColor = mix(baseColor, edgeColor, borderMask);
    const finalOpacity = alpha;

    material = new MeshPhysicalNodeMaterial({
      colorNode: finalColor,
      opacityNode: finalOpacity,
      emissiveNode: edgeColor.mul(borderMask),
      roughness: 0.55,
      metalness: 0.2,
      clearcoat: 0.15,
      transparent: true,
      side: THREE.DoubleSide,
      depthWrite: false,
    });

    mesh = new THREE.Mesh(geometry, material);
    mesh.castShadow = false;
    mesh.receiveShadow = false;
    pivot.add(mesh);

    const settle = gsap.fromTo(pivot.scale, { x: 1.04, y: 1.04, z: 1.04 }, { x: 1, y: 1, z: 1, duration: 0.9, ease: 'power4.out' });
    timelines.push(settle);
  });

  const triggerHover = (isHover) => {
    if (!material) return;
    gsap.killTweensOf(edgeUniform.value);
    gsap.killTweensOf(pivot.position);
    gsap.killTweensOf(pivot.scale);

    if (isHover) {
      timelines.push(gsap.to(pivot.position, { z: 0.15, duration: 0.35, ease: 'power2.out' }));
      timelines.push(gsap.to(pivot.scale, { x: 1.03, y: 1.03, z: 1.03, duration: 0.35, ease: 'power2.out' }));
      timelines.push(gsap.to(edgeUniform.value, { value: 2.2, duration: 0.35, ease: 'power2.out' }));
    } else {
      timelines.push(gsap.to(pivot.position, { z: 0, duration: 0.35, ease: 'power2.out' }));
      timelines.push(gsap.to(pivot.scale, { x: 1, y: 1, z: 1, duration: 0.35, ease: 'power2.out' }));
      timelines.push(gsap.to(edgeUniform.value, { value: 1.2, duration: 0.35, ease: 'power2.out' }));
    }
  };

  const triggerPress = () => {
    if (!material) return;
    const pressTl = gsap.timeline();
    pressTl.to(pivot.scale, { x: 0.97, y: 0.97, z: 0.97, duration: 0.12, ease: 'back.out(1.7)' })
           .to(pivot.scale, { x: 1.03, y: 1.03, z: 1.03, duration: 0.18, ease: 'power2.out' });
    timelines.push(pressTl);
    if (typeof ctx.emit === 'function') {
      ctx.emit('hub-pricing.select', { source: config.id || 'pricing-badge' });
    }
  };

  if (Array.isArray(config.cinematicPrimitives)) {
    for (const prim of config.cinematicPrimitives) {
      if (ctx.primitives && ctx.primitives[prim.name]) {
        const result = ctx.primitives[prim.name](pivot, prim.params || {});
        if (result && typeof result.cleanup === 'function') {
          timelines.push(result.timeline);
        }
      }
    }
  }

  root.userData.handlers = {
    hoverIn: () => triggerHover(true),
    hoverOut: () => triggerHover(false),
    click: triggerPress,
    onPointerOver: () => triggerHover(true),
    onPointerOut: () => triggerHover(false),
    onClick: triggerPress,
  };

  root.userData.cleanup = () => {
    timelines.forEach((tl) => { if (tl && tl.kill) tl.kill(); });
    if (geometry) geometry.dispose();
    if (material) material.dispose();
    if (tex && tex.dispose) tex.dispose();
    root.traverse((obj) => {
      if (obj.geometry) obj.geometry.dispose();
      if (obj.material) {
        if (Array.isArray(obj.material)) obj.material.forEach((m) => m.dispose());
        else obj.material.dispose();
      }
    });
  };

  return root;
}
